record.field:
{
    "type": "object",
    "properties": {
        "model_name": {
            "type": "string",
            "description": "Odoo technical model name, e.g. sale.order, res.partner"
        },
        "search_term": {
            "type": "string",
            "description": "Filter by method name, e.g. 'confirm'. Empty string to list all business methods."
        }
    },
    "required": ["model_name", "search_term"]
}

{
    "type": "object",
    "properties": {
        "search_term": {
            "type": "string",
            "description": "Filter by skill name. Empty string to list all."
        }
    },
    "required": ["search_term"]
}

{
    "type": "object",
    "properties": {
        "skill_id": {
            "type": "number",
            "description": "Database ID of the skill (from List Skills or a previous create)."
        }
    },
    "required": ["skill_id"]
}

{
    "type": "object",
    "properties": {
        "name": {
            "type": "string",
            "description": "Short action name, e.g. 'Create Sales Quotation'"
        },
        "model_name": {
            "type": "string",
            "description": "Technical name of the model the skill operates on, e.g. sale.order"
        },
        "description": {
            "type": "string",
            "description": "Tool description for the LLM: what it does, when to use it (trigger phrases), what it returns."
        },
        "schema_json": {
            "type": "string",
            "description": "JSON schema of the parameters as a JSON STRING. Follow the schema rules from your instructions strictly."
        },
        "code": {
            "type": "string",
            "description": "Python code. Schema properties are injected as local variables; end with ai['result'] = '...'. No sudo(), no system models."
        }
    },
    "required": ["name", "model_name", "description", "schema_json", "code"]
}

{
    "type": "object",
    "properties": {
        "skill_id": {
            "type": "number",
            "description": "Database ID of the skill to update."
        },
        "name": {
            "type": "string",
            "description": "New name, or empty string to keep the current one."
        },
        "description": {
            "type": "string",
            "description": "New description, or empty string to keep the current one."
        },
        "schema_json": {
            "type": "string",
            "description": "New JSON schema as a JSON string, or empty string to keep the current one."
        },
        "code": {
            "type": "string",
            "description": "New python code, or empty string to keep the current one."
        }
    },
    "required": ["skill_id", "name", "description", "schema_json", "code"]
}

{
    "type": "object",
    "properties": {
        "skill_id": {
            "type": "number",
            "description": "Database ID of the skill to test."
        },
        "arguments_json": {
            "type": "string",
            "description": "Sample arguments as a JSON object string matching the skill schema, e.g. {\"customer_name\": \"TEST Customer ABC\"}"
        }
    },
    "required": ["skill_id", "arguments_json"]
}

{
    "type": "object",
    "properties": {
        "skill_id": {
            "type": "number",
            "description": "Database ID of the draft skill to activate."
        }
    },
    "required": ["skill_id"]
}

{
    "type": "object",
    "properties": {
        "skill_id": {
            "type": "number",
            "description": "Database ID of the skill to deactivate."
        }
    },
    "required": ["skill_id"]
}
